<?php
require_once __DIR__.'/PayrollRepository.php';require_once __DIR__.'/../core/Response.php';
class PayrollSlipRenderer
{
    public static function data(int $id,bool $employee=false,bool $pdf=false): array{$slip=PayrollRepository::slip($id,$employee);if(!$slip)throw new RuntimeException('payroll_slip_not_available');$values=PayrollRepository::values($id,$employee,$pdf);$groups=['earning'=>[],'deduction'=>[],'info'=>[],'calculated'=>[],'employer_cost'=>[]];foreach($values as $value)$groups[$value['field_type']??'info'][]=$value;return compact('slip','groups');}
    public static function fragment(array $data): string{$slip=$data['slip'];$g=$data['groups'];ob_start();?><article class="payroll-paper" dir="rtl"><header><div><?php if(setting('logo_path')):?><img src="<?=e(setting('logo_path'))?>" alt="لوگو"><?php endif?><div><strong><?=e(setting('company_name','شرکت پخش سبحان'))?></strong><span>فیش حقوقی <?=e($slip['period_title'])?></span></div></div><dl><div><dt>کد رهگیری</dt><dd><?=e(substr($slip['tracking_code'],0,16))?></dd></div><div><dt>تاریخ صدور</dt><dd><?=e(format_jalali_date($slip['published_at']?:$slip['updated_at']))?></dd></div></dl></header><section class="payroll-person"><div><span>نام و نام خانوادگی</span><strong><?=e($slip['employee_name'])?></strong></div><div><span>شماره پرسنلی</span><strong><?=e($slip['employee_no'])?></strong></div><div><span>واحد</span><strong><?=e($slip['unit_title']?:$slip['department'])?></strong></div><div><span>سمت</span><strong><?=e($slip['job_title']?:$slip['role_key'])?></strong></div></section><section class="payroll-columns"><div><h3>مزایا</h3><table><?php foreach($g['earning'] as $v):?><tr><td><?=e($v['label'])?></td><td><?=e(format_money($v['value_number']))?></td></tr><?php endforeach?></table></div><div><h3>کسورات</h3><table><?php foreach($g['deduction'] as $v):?><tr><td><?=e($v['label'])?></td><td><?=e(format_money($v['value_number']))?></td></tr><?php endforeach?></table></div></section><?php if($g['info']):?><section class="payroll-info"><h3>اطلاعات تکمیلی</h3><div><?php foreach($g['info'] as $v):?><p><span><?=e($v['label'])?></span><strong><?=e(in_array($v['data_type'],['money','number'],true)?format_money($v['value_number']):$v['value_text'])?></strong></p><?php endforeach?></div></section><?php endif?><footer><div><span>جمع مزایا</span><strong><?=e(format_money($slip['total_earnings']))?></strong></div><div><span>جمع کسورات</span><strong><?=e(format_money($slip['total_deductions']))?></strong></div><div class="net"><span>خالص پرداختی</span><strong><?=e(format_money($slip['net_pay']))?> ریال</strong></div></footer></article><?php return (string)ob_get_clean();}
    public static function page(array $data,bool $print=false): string{$fragment=self::fragment($data);return '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>فیش حقوقی</title><link rel="stylesheet" href="/assets/css/workforce.css"><style>@page{size:A4 portrait;margin:12mm}</style></head><body class="payroll-output">'.$fragment.($print?'<script>addEventListener("load",()=>window.print())</script>':'').'</body></html>';}
}
